# codex-lsp shell integration for PowerShell. Capture checks current config and variables at every
# prompt; unchanged snapshots are not written again.
# Generated by 'codex-lsp env shell-init pwsh'.
if (-not $global:__CodexLspInstalled) {
	$global:__CodexLspInstalled = $true
	# Each interactive shell owns a fresh id; an inherited id belongs to the parent shell.
	$env:CODEX_LSP_CONTEXT_ID = "env-ps-$PID-$([guid]::NewGuid().ToString('N'))"
	$global:__CodexLspPrompt = $function:prompt
	function global:prompt {
		$code = $global:LASTEXITCODE
		& @NODE@ @CLI@ env capture --kind shell --shell pwsh | Out-Null
		if ($LASTEXITCODE -ne 0) { Write-Warning 'codex-lsp: environment capture failed' }
		$global:LASTEXITCODE = $code
		& $global:__CodexLspPrompt
	}
}
